/** The name of a judged scene. */
export type SceneName = keyof typeof SCENES

const arrow = Adornment.make({
  frame: Frame.make({ width: 9, height: 8, offsetLeft: 4 }),
  at: 1,
  orient: Adornment.orient.forward,
})
const label = Adornment.make({ frame: Frame.make({ width: 40, height: 16 }) })

/**
 * A judged scene, as `Connector.apply` takes it, with the playground's
 * settings: corners of radius 16, strokes 1.75 wide, and merged sides.
 *
 * @param name - The scene.
 * @returns Its rects, edges, and spec.
 */
export function sceneOf(name: SceneName) {
  const moved: Readonly<Record<string, readonly [number, number]>> = SCENES[name]
  const rects: Record<string, Rect.Rect> = {}
  for (const [id, [x, y, width, height]] of Object.entries(RECTS)) {
    const [left, top] = moved[id] ?? [x, y]
    rects[id] = Rect.make(left, top, width, height)
  }
  const edges = EDGES.map(([source, target, labeled]) =>
    Edge.make({
      source,
      target,
      radius: 16,
      thickness: 1.75,
      adornments: labeled ? [arrow, label] : [arrow],
    }),
  )
  const spec = Connector.make({
    clearance: 16,
    gap: 8,
    jogSlant: 2,
    merge: Connector.merge.side,
    mergeGap: 4,
  })
  return { rects, edges, spec }
}

interface Render {
  // Each route as its points, `x,y`, with the reach of the corner as a
  // third number where it has one; `null` for an edge without a route.
  readonly routes: ReadonlyArray<string | null>
  readonly notes: ReadonlyArray<Connector.ConnectorNote>
}

