/** The name of a judged render. */
export type RenderName = keyof typeof RENDERS

/**
 * A judged render, as the layout it drew. Its routes carry only what the
 * score reads: their points and the reach of their corners.
 *
 * @param name - The render.
 * @returns Its layout.
 */
export function layoutOf(name: RenderName): Connector.ConnectorLayout {
  const { routes, notes }: Render = RENDERS[name]
  return {
    edges: routes.map((route) => {
      if (route === null) {
        return undefined
      }
      const points = route.split(' ').map((point) => point.split(',').map(Number))
      return {
        points: points.map(([x, y]) => Point.make(x as number, y as number)),
        radii: points.map(([, , reach]) => reach ?? 0),
        outsets: points.map(() => 0),
        adornments: [],
        merged: [-1, -1],
      }
    }),
    notes,
  }
}
